#!/usr/bin/env node
/**
 * App version shown in the profile footer and the admin header (1.209, 1.210, …).
 *
 * version/admin-panel.json "build" is the displayed minor.
 * Older checkouts stored the next build there and the current one in the
 * generated file (json = ts + 1). Both layouts are still read.
 *
 * --commit  stamp parent + 1 and include it in the commit being created
 * --sync    rewrite the generated file so it matches the json (no increment)
 */
import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, '..');
const jsonPath = path.join(root, 'version/admin-panel.json');
const outPath = path.join(root, 'lib/generated/admin-panel-version.ts');

function readJsonBuild(text) {
  const data = JSON.parse(text);
  const build = Number(data.build);
  if (!Number.isFinite(build) || build < 1) {
    throw new Error('version/admin-panel.json must have a positive numeric "build" field');
  }
  return build;
}

function readTsBuild(text) {
  const match = String(text).match(/ADMIN_PANEL_VERSION = '(\d+)\.(\d+)'/);
  if (!match) return null;
  const build = Number(match[2]);
  return Number.isFinite(build) ? build : null;
}

/** Build number a checkout is actually showing. */
function displayedBuild(jsonBuild, tsBuild) {
  if (tsBuild != null && jsonBuild === tsBuild + 1) return tsBuild;
  return jsonBuild;
}

function versionSource(build) {
  return `/** Auto-generated by scripts/bump-admin-panel-version.mjs — do not edit */\nexport const ADMIN_PANEL_VERSION = '1.${build}';\n`;
}

function gitShow(spec) {
  try {
    return execSync(`git show ${spec}`, {
      cwd: root,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    });
  } catch {
    return null;
  }
}

function writeVersion(build) {
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(jsonPath, `${JSON.stringify({ build }, null, 2)}\n`);
  fs.writeFileSync(outPath, versionSource(build));
}

const mode = process.argv.includes('--commit') ? 'commit' : 'sync';
const jsonBuild = readJsonBuild(fs.readFileSync(jsonPath, 'utf8'));
const tsBuild = readTsBuild(fs.existsSync(outPath) ? fs.readFileSync(outPath, 'utf8') : '');

if (mode === 'sync') {
  const shown = displayedBuild(jsonBuild, tsBuild);
  const nextSource = versionSource(shown);
  if (!fs.existsSync(outPath) || fs.readFileSync(outPath, 'utf8') !== nextSource) {
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, nextSource);
  }
  console.log(`[app-version] v1.${shown}`);
} else {
  const parentJsonText = gitShow('HEAD:version/admin-panel.json');
  const parentTsText = gitShow('HEAD:lib/generated/admin-panel-version.ts');
  const parentJson = parentJsonText ? readJsonBuild(parentJsonText) : jsonBuild;
  const parentTs = parentTsText ? readTsBuild(parentTsText) : tsBuild;
  const parentShown = displayedBuild(parentJson, parentTs);
  const next = parentJsonText ? parentShown + 1 : displayedBuild(jsonBuild, tsBuild);

  writeVersion(next);
  console.log(`[app-version] v1.${next}`);
}
